# apply_playoff_and_run.py — adds is_playoff_driver + is_elimination_race features
# and compares matchup LL, with a playoff-race breakout to test the deference hypothesis.
import base64, sys, pathlib

FILES = {
    'src/features/playoffs.py': '',
    'src/features/build_features.py': '',
    'src/models/gbm_ranker.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import pandas as pd
    from src.eval.backtest_gbm_walkforward import backtest_gbm_walkforward, summarize_wf

    TIGHT_REG = {"num_leaves": 31, "min_data_in_leaf": 25, "lambda_l2": 2.0}

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")
    laptimes = pd.read_parquet("data/processed/laptimes.parquet")

    print("\n=== A. previous best (features build_features already has playoff cols now, ensemble=3) ===")
    out = backtest_gbm_walkforward(
        races, entries, sessions, loopstats, laptimes=laptimes,
        initial_train_races=36, retrain_every_n=10,
        calib_window=25, recalibrate_every_n=10,
        ensemble_alpha=0.85, n_samples=3000,
        gbm_fit_kwargs=TIGHT_REG,
        n_ensemble=3,
    )
    df = out["metrics"]
    print(summarize_wf(df).round(4).to_string())

    # ------------------------------------------------------------------------
    # Playoff-race breakout: is the effect concentrated where we expect?
    # ------------------------------------------------------------------------
    # Attach playoff_round back onto the per-race metrics so we can slice.
    r_lookup = races.set_index("race_id_short")[["playoff_round", "season"]]
    df = df.merge(r_lookup, left_on="race_id", right_index=True, how="left")
    df["is_playoff_race"] = (df["playoff_round"] > 0).astype(int)

    by_playoff = df.groupby("is_playoff_race").agg(
        n_races=("race_id", "count"),
        matchup_ll=("matchup_logloss", "mean"),
        winner_ll=("winner_logloss", "mean"),
        spearman=("spearman_rho", "mean"),
        top5=("top5_accuracy", "mean"),
    ).round(4)
    print("\nBy regular-season vs. playoff-race:")
    print(by_playoff.to_string())

    by_round = df.groupby("playoff_round").agg(
        n_races=("race_id", "count"),
        matchup_ll=("matchup_logloss", "mean"),
    ).round(4)
    print("\nBy playoff round:")
    print(by_round.to_string())

    # Feature importance for the new flags.
    try:
        booster = out["model"].booster
        imp = pd.DataFrame({
            "feature": booster.feature_name(),
            "gain": booster.feature_importance(importance_type="gain"),
        }).sort_values("gain", ascending=False).reset_index(drop=True)
        for f in ["is_playoff_driver", "is_elimination_race", "playoff_round", "in_playoffs", "races_to_cutoff"]:
            row = imp[imp["feature"] == f]
            if len(row):
                rank = int(imp.index[imp["feature"] == f][0]) + 1
                print(f"  {f}: gain={row['gain'].iloc[0]:.1f}, rank #{rank}")
    except Exception as e:
        print(f"(feat importance skipped: {e})")

if __name__ == "__main__":
    main()

